import {Arena} from './arena.js';
import {BASE_PROGRAM,PRESETS,validateProgram,inspectProgram} from './program.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const initial=()=>({program:structuredClone(BASE_PROGRAM),previous:null,selected:'ricochet',proposals:PRESETS.map((p,i)=>({...p,votes:0,voted:false,createdAt:Date.now()-i*1000,sample:true})),history:[],battles:[],author:'Your workshop',level:1,trait:'Feather warning',traitDescription:'Eight feathers. One circle. Plenty of room to panic.',version:1});
let state=initial(),mode='practice',sort='top',activeView='forge',toastTimer,serviceUrl='',adminToken='',room='',socket,connectionEpoch=0,forgeBusy=false,pendingMutation=null;
try{const saved=JSON.parse(localStorage.getItem('raidforge-v1'));if(saved){validateProgram(saved.program);if(!Array.isArray(saved.proposals)||!Array.isArray(saved.history)||!Array.isArray(saved.battles))throw Error();state={...initial(),...saved};}}catch{}
let practiceState=structuredClone(state);
const overlay=new URLSearchParams(location.search).has('overlay');if(overlay)document.body.classList.add('overlay');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function save(){if(mode==='practice'){try{localStorage.setItem('raidforge-v1',JSON.stringify(state));practiceState=structuredClone(state);}catch{$('#save-label').textContent='Storage full — changes not saved';}}render();}
function showModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(forgeBusy)return;$('#modal').close();if(arena.preview){arena.stop();restoreArena();}}
$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});$('#modal').addEventListener('cancel',e=>{if(forgeBusy)e.preventDefault();else if(arena.preview){arena.stop();restoreArena();}});
function timeLabel(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
const arena=new Arena($('#arena'),{
 onUpdate:s=>{$('#boss-health-number').textContent=`${Math.ceil(s.bossHp)}%`;$('#boss-health-fill').style.width=`${s.bossHp}%`;$('#player-hearts').textContent='♥ '.repeat(Math.max(0,s.playerHp))+'♡ '.repeat(5-Math.max(0,s.playerHp));$('#fight-timer').textContent=timeLabel(s.time);},
 onPause:paused=>{if(paused){$('#arena-message').innerHTML='<h2>TAKE A BREATHER.</h2><p>The goose can wait.</p><button class="button primary" id="resume-button">Resume fight →</button>';$('#arena-message').hidden=false;$('#resume-button').onclick=()=>arena.pause();}else $('#arena-message').hidden=true;},
 onEnd:result=>{const record={...result,id:uid(),at:new Date().toISOString(),boss:state.program.name};if(mode==='live'){api('/api/battle',{result:record}).catch(e=>toast(e.message));}else{state.battles.push(record);state.battles=state.battles.slice(-100);save();}$('#arena-status').textContent=result.won?'BOSS DEFEATED':'CHALLENGER DEFEATED';$('#arena-message').innerHTML=`<h2>${result.won?'GOOSE. COOKED.':'THE GOOSE WINS.'}</h2><p>${result.won?'You survived your community’s imagination. Time to make it someone else’s problem.':'Every monster needs a worthy challenger. Shake it off and go again.'}<br><strong>${timeLabel(result.time)}</strong> in the arena</p><button class="button primary" id="retry-button">${result.won?'Fight again':'One more round'} →</button><button class="text-button" id="leave-button" style="margin-top:18px">Back to the workshop</button>`;$('#arena-message').hidden=false;$('#retry-button').onclick=startFight;$('#leave-button').onclick=()=>{arena.stop();restoreArena();};$('#fight-button').innerHTML='↻ Try again <span>→</span>';},
 onFrame:frame=>{if(mode==='live'&&socket?.readyState===WebSocket.OPEN&&!overlay)socket.send(JSON.stringify({type:'frame',frame}));}
});
function restoreArena(){arena.setProgram(state.program);$('#boss-title').hidden=false;$('#fight-hud').hidden=true;$('#arena-message').hidden=true;$('#mobile-dash').hidden=true;$('#arena-status').textContent='AWAITING CHALLENGER';$('#fight-button').innerHTML='<span>⚔</span> Enter the arena <span>→</span>';$('#action-kicker').textContent='THINK YOU CAN TAKE HIM?';$('#action-description').textContent='Your chat made a monster. Make them regret it.';}
function startFight(){if(forgeBusy)return;if(arena.preview)arena.stop();arena.setProgram(state.program);arena.start();$('#boss-title').hidden=true;$('#fight-hud').hidden=false;$('#arena-message').hidden=true;$('#mobile-dash').hidden=!matchMedia('(pointer:coarse)').matches;$('#arena-status').textContent='FIGHT IN PROGRESS';$('#fight-button').innerHTML='↶ Leave arena';$('#action-kicker').textContent='THE GOOSE HAS CHOSEN VIOLENCE';$('#action-description').textContent='Hold Space to auto-aim. Dash through feathers with Shift.';if(innerWidth<900)$('#arena-wrap').scrollIntoView({block:'center',behavior:'smooth'});}
$('#fight-button').onclick=()=>{if(arena.preview&&pendingMutation){arena.stop();restoreArena();reviewMutation(pendingMutation.program,pendingMutation.p,pendingMutation.generationId);return;}if(arena.mode==='playing'||arena.mode==='paused'){arena.stop();restoreArena();}else startFight();};$('#mobile-dash').onclick=()=>arena.dash();
$('#sound-button').onclick=()=>{arena.sound=!arena.sound;if(arena.sound)arena.beep(440,.1);$('#sound-button').style.color=arena.sound?'#ff784d':'';$('#sound-button').setAttribute('aria-label',arena.sound?'Mute sound':'Enable sound');toast(arena.sound?'Arena sound enabled':'Arena sound muted');};
$('#fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#arena-wrap').requestFullscreen();}catch{toast('Full screen is not available in this browser.');}};
function render(){
 $('#mode-label').textContent=mode==='live'?`LIVE / ${room.toUpperCase()}`:'PRACTICE WORKSHOP';$('#save-label').textContent=mode==='live'?'Synced with your service':'Saved on this device';$('#boss-name').textContent=state.program.name.toUpperCase();$('#hud-boss-name').textContent=state.program.name.toUpperCase();$('#boss-tagline').textContent=state.program.tagline;$('#boss-level').textContent=String(state.level).padStart(2,'0');$('#origin-label').textContent=state.author;$('#attack-count').innerHTML=`${state.program.patterns.length} <small>equipped</small>`;$('#battle-count').innerHTML=`${state.battles.length} <small>fought</small>`;$('#raid-count').innerHTML=`${state.history.length} <small>and counting</small>`;$('#trait-title').textContent=state.trait;$('#trait-description').textContent=state.traitDescription;$('#history-count').textContent=String(state.history.length).padStart(2,'0');$('#rollback-button').hidden=!state.previous;$('#queue-count').textContent=state.proposals.length;$('#sample-label').textContent=mode==='live'?'TWITCH CHAT':'PRACTICE IDEAS';$('#arena-mode-note').textContent=mode==='live'?`CONNECTED TO ${room.toUpperCase()}`:'LOCAL PRACTICE • NO TWITCH CONNECTION';$('#forge-caption').textContent=mode==='live'?'Generated with Codex · checked before activation':'Practice presets · live Codex available on connect';
 $('#connect-button').innerHTML=mode==='live'?`<span class="live-dot"></span> ${escape(room)} <span>⚙</span>`:'<svg viewBox="0 0 24 24"><path d="M5 3h16v12l-5 5h-4l-3 3v-3H5zM10 7v6m6-6v6"/></svg>Connect Twitch <span>→</span>';
 $('#proposals').replaceChildren();const proposals=[...state.proposals].sort((a,b)=>sort==='top'?b.votes-a.votes:b.createdAt-a.createdAt);for(const p of proposals){const card=document.createElement('div');card.className=`proposal-card ${p.id===state.selected?'selected':''}`;card.tabIndex=0;card.role='button';card.setAttribute('aria-label',`Select ${p.title}`);card.setAttribute('aria-pressed',p.id===state.selected);card.innerHTML=`<button class="vote-button ${p.voted?'voted':''}" aria-label="Vote for ${escape(p.title)}" ${mode==='live'?'disabled title="Vote in Twitch chat with !vote '+escape(p.number)+'"':''}><span>▲</span>${p.votes}</button><div class="proposal-main"><div class="proposal-author"><span class="mini-avatar">${escape(p.author[0]?.toUpperCase()||'Y')}</span>${escape(p.author)}${p.number?` · #${p.number}`:''}</div><b>${escape(p.title)}</b><span class="proposal-label">${escape(p.label||'COMMUNITY IDEA')}</span></div>`;const select=()=>{state.selected=p.id;render();};card.onclick=select;card.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target===card){e.preventDefault();select();}};card.querySelector('.vote-button').onclick=e=>{e.stopPropagation();if(mode==='live')return;const target=state.proposals.find(x=>x.id===p.id);target.voted=!target.voted;target.votes+=target.voted?1:-1;save();};$('#proposals').append(card);}
 const selected=state.proposals.find(p=>p.id===state.selected);$('#forge-description').textContent=selected?`Selected: ${selected.title}`:'Select a mutation to preview its attack.';$('#forge-button').disabled=forgeBusy||!selected;if(activeView==='bestiary')renderBestiary();if(activeView==='history')renderHistory();
}
$$('[data-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.sort;$$('[data-sort]').forEach(x=>x.classList.toggle('active',x===b));render();});
$('#proposal-input').oninput=e=>$('#char-count').textContent=`${e.target.value.length}/240`;
$('#proposal-form').onsubmit=async e=>{e.preventDefault();const input=$('#proposal-input'),prompt=input.value.trim();if(prompt.length<8){toast('Give your idea a little more detail (at least 8 characters).');return;}try{if(mode==='live')await api('/api/proposal',{prompt});else{const proposal={id:uid(),title:prompt,prompt,author:'you',label:'YOUR IDEA',votes:1,voted:true,createdAt:Date.now(),sample:false};state.proposals.unshift(proposal);state.proposals=state.proposals.slice(0,30);state.selected=proposal.id;save();}input.value='';$('#char-count').textContent='0/240';toast(mode==='live'?'Proposal added to your live queue.':'Idea saved. Connect Codex to forge custom attacks.');}catch(err){toast(err.message);}};
function activate(program,proposal){state.previous={program:state.program,trait:state.trait,traitDescription:state.traitDescription,level:state.level};state.program=validateProgram(program);state.trait=proposal.title;state.traitDescription=`Forged from ${proposal.author}’s idea. ${program.tagline}`;state.level++;save();arena.stop();restoreArena();toast('Mutation equipped. The goose has learned a new trick.');}
$('#forge-button').onclick=async()=>{const p=state.proposals.find(x=>x.id===state.selected);if(!p||forgeBusy)return;if(pendingMutation?.p.id===p.id&&pendingMutation.mode===mode){arena.stop();restoreArena();reviewMutation(pendingMutation.program,p,pendingMutation.generationId);return;}if(arena.mode==='playing'||arena.mode==='paused'){toast('Finish or leave the current fight before forging.');return;}
 if(mode==='practice'&&!p.program){showModal('<div class="modal-eyebrow">YOUR IDEA IS SAVED</div><h2>Let Codex do the forging.</h2><p>Custom ideas need the RAIDFORGE service connected to an authenticated Codex installation. Practice mode includes three playable example mutations.</p><div class="modal-actions"><button class="button primary" id="connect-from-forge">Connect service →</button><button class="button ghost" id="preset-from-forge">Try a preset</button></div>');$('#connect-from-forge').onclick=showConnect;$('#preset-from-forge').onclick=()=>{state.selected=state.proposals.find(x=>x.program)?.id;closeModal();render();};return;}
 let program=p.program,generationId;
 if(mode==='live'){forgeBusy=true;render();showModal('<div class="modal-eyebrow">CODEX AT THE WORKBENCH</div><h2>Making your bad idea real.</h2><p>Your current boss stays intact while Codex writes a bounded attack program.</p><div class="progress-row"><span class="spinner"></span> Generating and validating attack behavior…</div><p class="muted-small">This can take a few minutes. Keep this window open.</p>');try{const result=await api('/api/forge',{proposalId:p.id},190000);program=result.program;generationId=result.id;}catch(err){forgeBusy=false;render();showModal(`<div class="modal-eyebrow">FORGE PAUSED</div><h2>The boss is unchanged.</h2><p class="error-text">${escape(err.message)}</p><p>Check the service’s Codex authentication, then try again.</p>`);return;}forgeBusy=false;render();}
 pendingMutation={program,p,generationId,mode};reviewMutation(program,p,generationId);
};
function reviewMutation(program,p,generationId){
 const report=inspectProgram(program);showModal(`<div class="modal-eyebrow">${mode==='live'?'CODEX GENERATED':'PRACTICE PRESET'} / READY TO PREVIEW</div><h2>${escape(p.title)}</h2><p>${escape(program.tagline)}</p><div class="checks">${report.checks.map(c=>`<div>${escape(c)}</div>`).join('')}<div>${report.patterns} patterns · ${report.maxBulletsPerSecond} projectiles / second</div></div><details><summary class="text-button">Inspect attack program</summary><pre>${escape(JSON.stringify(program,null,2))}</pre></details><div class="modal-actions"><button class="button ghost" id="preview-mutation">Watch test arena</button><button class="button primary" id="equip-mutation">Equip mutation →</button></div><p class="muted-small">${mode==='live'?'Generated for this proposal.':'This is a curated example, not a live AI generation.'} Preview is an automated demonstration, not a proof of game balance.</p>`);
 $('#preview-mutation').onclick=()=>{$('#modal').close();arena.setProgram(program);arena.start(true);$('#boss-title').hidden=true;$('#fight-hud').hidden=false;$('#arena-status').textContent='AUTOMATED PREVIEW';$('#fight-button').innerHTML='Stop preview & review →';$('#action-kicker').textContent='TEST ARENA / AUTO-PILOT';$('#action-description').textContent='Preview only. Stop to review and equip this exact mutation.';};
 $('#equip-mutation').onclick=async()=>{try{if(mode==='live'){await api('/api/equip',{generationId});arena.stop();restoreArena();toast('Codex mutation equipped.');}else activate(program,p);pendingMutation=null;closeModal();}catch(err){toast(err.message);}};
};
$('#rollback-button').onclick=async()=>{if(arena.mode==='playing'||arena.mode==='paused'){toast('Leave the fight before restoring a mutation.');return;}if(!state.previous)return;try{if(mode==='live')await api('/api/rollback',{});else{const prev=state.previous;Object.assign(state,prev);state.previous=null;save();}restoreArena();toast('Previous mutation restored.');}catch(e){toast(e.message);}};
function setView(view){activeView=view;$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));['forge','bestiary','history'].forEach(v=>$(`#${v}-view`).hidden=v!==view);if(view==='bestiary')renderBestiary();if(view==='history')renderHistory();}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function renderBestiary(){const wins=state.battles.filter(b=>b.won).length;$('#bestiary-view').innerHTML=`<div class="eyebrow">YOUR COLLECTION OF QUESTIONABLE DECISIONS</div><h2 class="secondary-title">THE BESTIARY.</h2><p class="secondary-description">Every mutation, every battle, every community. Your boss carries its story.</p><div class="collection"><article class="collection-card"><span class="eyebrow">SPECIMEN 001 / LEVEL ${state.level}</span><div class="goose-mini">🪿</div><h3>${escape(state.program.name)}</h3><p>${escape(state.program.tagline)}<br>${state.program.patterns.length} attack patterns · ${wins} victories · ${state.history.length} handoffs</p><button class="button primary" id="bestiary-play">Back to the arena →</button><button class="button ghost" id="bestiary-export">Export</button></article><article class="collection-card"><span class="eyebrow">BRING YOUR OWN MONSTER</span><div class="goose-mini">↙</div><h3>Continue the story.</h3><p>Import a RAIDFORGE boss file from another workshop. Programs are validated before loading.</p><label class="button ghost">Import boss file<input id="import-file" type="file" accept="application/json,.json" hidden></label></article></div>`;$('#bestiary-play').onclick=()=>setView('forge');$('#bestiary-export').onclick=exportBoss;$('#import-file').onchange=importBoss;}
function renderHistory(){$('#history-view').innerHTML=`<div class="eyebrow">ONE MONSTER. MANY COMMUNITIES.</div><h2 class="secondary-title">THE RAID TRAIL.</h2><p class="secondary-description">Follow the chaos from its first workshop to its next challenger.</p>${state.history.length?`<div class="timeline">${[...state.history].reverse().map(h=>`<article class="timeline-entry"><time>${escape(new Date(h.at).toLocaleString())} · ${h.practice?'PRACTICE HANDOFF':'TWITCH RAID'}</time><h3>${escape(h.from)} <span style="color:var(--accent)">→</span> ${escape(h.to)}</h3><p>${escape(h.boss)} traveled with ${h.viewers??0} ${h.practice?'practice travelers':'viewers'}.<br>${escape(h.note||'The story continues.')}</p></article>`).join('')}</div>`:'<div class="empty-state"><div class="empty-icon">→</div><h3>A legend has to start somewhere.</h3><p>Your boss hasn’t traveled yet.<br>Prepare a raid to give its story a second chapter.</p><button class="button raid-button" id="history-raid">Prepare a raid →</button></div>'}`;if($('#history-raid'))$('#history-raid').onclick=showRaid;}
function exportBoss(){const payload={format:'raidforge-boss-v1',program:state.program,author:state.author,level:state.level,trait:state.trait,traitDescription:state.traitDescription,history:state.history};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='raidforge-honkfather.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Boss exported with its attack program and history.');}
$('#export-button').onclick=exportBoss;
async function importBoss(e){if(mode==='live'){toast('Switch to practice to import a boss.');return;}try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Boss file is too large.');const data=JSON.parse(await file.text());if(data.format!=='raidforge-boss-v1')throw Error('Not a RAIDFORGE boss file.');const program=validateProgram(data.program);state.previous={program:state.program,trait:state.trait,traitDescription:state.traitDescription,level:state.level};state.program=program;state.author=String(data.author||'Imported workshop').slice(0,60);state.level=Math.min(99,Math.max(1,Number(data.level)||1));state.trait=String(data.trait||'Imported mutation').slice(0,240);state.traitDescription=String(data.traitDescription||program.tagline).slice(0,300);state.history=Array.isArray(data.history)?data.history.slice(-100).map(h=>({from:String(h.from||'Unknown').slice(0,60),to:String(h.to||'Unknown').slice(0,60),at:Number.isNaN(Date.parse(h.at))?new Date().toISOString():h.at,practice:true,boss:program.name,viewers:0,note:'Imported history (unverified).'})):[];state.battles=[];save();restoreArena();toast('Boss imported and validated.');}catch(err){toast(err.message);}}
function showRaid(){showModal(`<div class="modal-eyebrow">${mode==='live'?'PREPARE THE HANDOFF':'PRACTICE HANDOFF'}</div><h2>Same goose.<br>Someone else’s problem.</h2><p>${mode==='live'?'Arm a handoff to a connected channel. When you perform the Twitch raid, the destination receives an invitation to accept your boss.':'Rehearse the handoff locally. This adds a labeled practice entry to the boss history; it does not initiate a Twitch raid.'}</p><form id="raid-form"><label for="raid-target">DESTINATION CHANNEL</label><input id="raid-target" name="target" required minlength="3" maxlength="25" pattern="[a-zA-Z0-9_]+" placeholder="channel_name" autocomplete="off"><div class="notice">${mode==='live'?'Both channels must be connected to this RAIDFORGE service. The receiving streamer must accept the boss. Start the actual raid from Twitch after arming the handoff.':'Your boss keeps its equipped attacks and creator credit. You can export its file to share the practice creation.'}</div><div class="modal-actions"><button type="submit" class="button primary">${mode==='live'?'Arm raid handoff':'Rehearse handoff'} →</button><button type="button" class="button ghost" id="raid-export">Export boss</button></div></form>`);$('#raid-export').onclick=exportBoss;$('#raid-form').onsubmit=async e=>{e.preventDefault();const target=$('#raid-target').value.toLowerCase();try{if(mode==='live'){await api('/api/raid/arm',{target});toast(`Handoff armed. Start /raid ${target} in Twitch.`);}else{state.history.push({from:state.history.at(-1)?.to||'your_workshop',to:target,boss:state.program.name,at:new Date().toISOString(),practice:true,viewers:0,note:'Local rehearsal. No Twitch raid was sent.'});save();toast(`Practice handoff recorded for ${target}.`);}closeModal();setView('history');}catch(err){toast(err.message);}};}
$('#raid-button').onclick=showRaid;
function showGuide(){showModal('<div class="modal-eyebrow">WELCOME TO THE FORGE</div><h2>Chat builds the boss.<br>You survive it.</h2><div class="steps-grid"><b>01</b><p><strong>Invent something terrible.</strong>Pick a practice mutation, or connect Twitch and let viewers submit <code>!forge your idea</code> and vote with <code>!vote 1</code>.</p><b>02</b><p><strong>Make it real.</strong>Preview the attack, then equip it. In live mode Codex generates a new bounded attack program. You approve every change.</p><b>03</b><p><strong>Enter the arena.</strong>Move with WASD or arrows. Hold Space to auto-aim and shoot, or aim with the mouse and hold click. Shift dashes through projectiles. Escape pauses. On touch screens, drag to move and auto-fire.</p><b>04</b><p><strong>Pass the problem along.</strong>Arm a handoff, raid a connected streamer on Twitch, and let them accept your monster. Its history travels with it.</p></div><div class="notice">This preview starts in local practice mode. There are no simulated live viewers, automatic votes, or pretend AI generations.</div><div class="modal-actions"><button class="button primary" id="guide-done">Let’s make a monster →</button></div>');$('#guide-done').onclick=closeModal;}
$('#guide-button').onclick=showGuide;$('#help-button').onclick=showGuide;
function showConnect(){showModal(`<div class="modal-eyebrow">CONNECT YOUR WORKSHOP</div><h2>Bring your chat into it.</h2><p>The live service connects Twitch EventSub and Codex to this arena. Run <code>npm install && npm start</code> from the source repository, then connect below.</p><form id="connect-form"><label for="service-url">RAIDFORGE SERVICE URL</label><input id="service-url" type="url" required value="${escape(serviceUrl||localStorage.getItem('raidforge-service')||(location.hostname.includes('chatgpt.site')?'':'http://localhost:3000'))}" placeholder="https://your-raidforge-service.example"><label for="admin-token">SERVICE ADMIN TOKEN</label><input id="admin-token" type="password" required autocomplete="off" placeholder="Your RAIDFORGE_ADMIN_TOKEN" value="${escape(adminToken)}"><label for="channel-name">YOUR TWITCH CHANNEL</label><input id="channel-name" required pattern="[a-zA-Z0-9_]{3,25}" placeholder="your_channel" value="${escape(room)}"><p class="muted-small">The admin token stays in this tab’s memory. Twitch credentials belong in the service’s .env file, never in this form.</p><div class="modal-actions"><button class="button primary" type="submit">Connect service →</button><button type="button" class="button ghost" id="use-practice">Use practice</button></div></form><div id="connection-status"></div>`);
 $('#use-practice').onclick=()=>{disconnect();closeModal();toast('Back in local practice mode.');};$('#connect-form').onsubmit=async e=>{e.preventDefault();const raw=$('#service-url').value.replace(/\/$/,'');const url=new URL(raw);if(url.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(url.hostname)){toast('Use HTTPS for a remote service.');return;}if(location.protocol==='https:'&&url.protocol!=='https:'){toast('The hosted preview requires an HTTPS service. Open the local app for localhost.');return;}const old={serviceUrl,adminToken,room};serviceUrl=raw;adminToken=$('#admin-token').value;room=$('#channel-name').value.toLowerCase();$('#connection-status').innerHTML='<p>Connecting to your service…</p>';try{const data=await api('/api/connect',{});if(mode==='practice')practiceState=structuredClone(state);mode='live';state=data.state;state.selected=state.proposals[0]?.id;localStorage.setItem('raidforge-service',serviceUrl);connectSocket();restoreArena();render();$('#connection-status').innerHTML=`<p class="success-text">Service connected. ${data.twitchConnected?'Twitch is receiving events.':'Authorize Twitch to receive chat and raids.'}</p><div class="modal-actions"><button class="button ghost" id="authorize-twitch">Authorize Twitch →</button><button class="button ghost" id="overlay-link">Copy OBS overlay URL</button></div><p class="muted-small">Codex must be authenticated on the service host for generation.</p>`;$('#authorize-twitch').onclick=authorizeTwitch;$('#overlay-link').onclick=copyOverlay;}catch(err){serviceUrl=old.serviceUrl;adminToken=old.adminToken;room=old.room;$('#connection-status').innerHTML=`<p class="error-text">${escape(err.message)}</p>`;}};
}
$('#connect-button').onclick=showConnect;
async function authorizeTwitch(){try{const result=await api('/api/twitch/authorize',{});location.href=result.url;}catch(e){toast(e.message);}}
async function copyOverlay(){const url=`${serviceUrl}/?overlay=1&room=${encodeURIComponent(room)}`;try{await navigator.clipboard.writeText(url);toast('OBS browser-source URL copied.');}catch{showModal(`<h2>Your OBS browser source</h2><input readonly value="${escape(url)}"><p>Use a 1000 × 667 browser source. Keep the main arena open to broadcast the fight.</p>`);}}
async function api(path,body,timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(serviceUrl+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${adminToken}`,'X-Raidforge-Room':room},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.error||`Service error (${response.status})`);if(data.state&&mode==='live'){state={...data.state,selected:state.selected};if(!state.proposals.some(x=>x.id===state.selected))state.selected=state.proposals[0]?.id;render();}return data;}catch(e){if(e.name==='AbortError')throw Error('The service did not respond in time. Your equipped boss is unchanged.');if(e instanceof TypeError)throw Error('Could not reach the service. Check its URL, HTTPS, and ALLOWED_ORIGINS.');throw e;}finally{clearTimeout(timer);}}
function disconnect(){pendingMutation=null;connectionEpoch++;socket?.close();socket=null;mode='practice';adminToken='';room='';state=structuredClone(practiceState);arena.stop();arena.remote=false;restoreArena();render();}
function connectSocket(){const epoch=++connectionEpoch;socket?.close();const wsUrl=serviceUrl.replace(/^http/,'ws')+'/ws';socket=new WebSocket(wsUrl);socket.onopen=()=>socket.send(JSON.stringify({type:'join',room,token:overlay?undefined:adminToken}));socket.onmessage=e=>{const data=JSON.parse(e.data);if(data.type==='state'){state={...data.state,selected:state.selected};if(!state.proposals.some(p=>p.id===state.selected))state.selected=state.proposals[0]?.id;render();if(arena.mode==='idle')arena.setProgram(state.program);if(data.state.incoming&&!overlay)showIncoming(data.state.incoming);}else if(data.type==='frame'&&overlay){arena.remote=true;arena.receiveFrame(data.frame);$('#boss-title').hidden=data.frame.mode!=='idle';$('#fight-hud').hidden=data.frame.mode==='idle';$('#arena-status').textContent=data.frame.mode==='playing'?'LIVE FIGHT':'CONNECTED';}else if(data.type==='error')toast(data.error);};socket.onclose=()=>{if(epoch!==connectionEpoch)return;$('#save-label').textContent='Service disconnected — reconnecting';setTimeout(()=>{if(epoch===connectionEpoch&&(mode==='live'||overlay))connectSocket();},4000);};socket.onerror=()=>{};}
let incomingShown;
function showIncoming(incoming){if(incomingShown===incoming.id)return;incomingShown=incoming.id;showModal(`<div class="modal-eyebrow">A MONSTER HAS ARRIVED</div><h2>${escape(incoming.program.name)}</h2><p>From <strong>${escape(incoming.from)}</strong>, with ${incoming.viewers} viewers and a very questionable attitude.</p><p>${escape(incoming.program.tagline)}</p><div class="modal-actions"><button class="button primary" id="accept-boss">Accept boss →</button><button class="button ghost" id="decline-boss">Keep my boss</button></div>`);$('#accept-boss').onclick=async()=>{try{await api('/api/raid/accept',{id:incoming.id});restoreArena();closeModal();toast('Boss accepted. Welcome to the next chapter.');}catch(e){toast(e.message);}};$('#decline-boss').onclick=async()=>{try{await api('/api/raid/decline',{id:incoming.id});closeModal();}catch(e){toast(e.message);}};}
$('#reset-button').onclick=()=>{if(mode==='live'){toast('Switch to practice before resetting local data.');return;}showModal('<div class="modal-eyebrow">RESET LOCAL PRACTICE</div><h2>A fresh start for the goose.</h2><p>This clears this device’s practice mutations, battles, votes, and handoff history. Export your boss first if you want to keep it.</p><div class="modal-actions"><button class="button ghost" id="reset-export">Export boss</button><button class="button primary" id="confirm-reset">Reset practice</button></div>');$('#reset-export').onclick=exportBoss;$('#confirm-reset').onclick=()=>{state=initial();save();arena.stop();restoreArena();closeModal();toast('Practice workshop reset.');};};
render();restoreArena();
if(overlay){serviceUrl=location.origin;room=new URLSearchParams(location.search).get('room')||'';arena.remote=true;fetch(`/api/rooms/${encodeURIComponent(room)}`).then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{state=data.state;mode='live';render();restoreArena();connectSocket();}).catch(()=>{$('#arena-status').textContent='OVERLAY NEEDS A LIVE SERVICE';$('#arena-mode-note').textContent='OPEN THIS URL ON YOUR RAIDFORGE SERVICE';});}
